mapper.select:
        select
id, camera_id, user_id, create_time, deal_time, deal_flag
        from camera_alarm


                and id = #{id}


                and camera_id = #{cameraId}


                and user_id = #{userId}


                and create_time = #{createTime}


                and deal_time = #{dealTime}


                and deal_flag = #{dealFlag}


        limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from camera_alarm


        and id = #{id}


        and camera_id = #{cameraId}


        and user_id = #{userId}


        and create_time = #{createTime}


        and deal_time = #{dealTime}


        and deal_flag = #{dealFlag}

SELECT COUNT(*)
FROM camera_alarm
WHERE DATE(create_time) = #{date}

SELECT COUNT(*)
FROM camera_alarm
WHERE create_time BETWEEN #{startTime} AND #{endTime}

    AND deal_flag = #{dealFlag}
